import { createChange, createController, definePrimitive, type ChangeDetails, type ChangeOptions } from "@ui-sdk/core"

type SidebarCollapsedChangeReason = "trigger-press" | "imperative"

type SidebarOptions = {
  collapsed?: boolean
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean, details: ChangeDetails<SidebarCollapsedChangeReason>) => void
  controller?: SidebarController
}

interface SidebarController {
  setCollapsed: (collapsed: boolean, options?: ChangeOptions<SidebarCollapsedChangeReason>) => boolean | undefined
  collapse: (options?: ChangeOptions<SidebarCollapsedChangeReason>) => boolean | undefined
  expand: (options?: ChangeOptions<SidebarCollapsedChangeReason>) => boolean | undefined
  toggle: (options?: ChangeOptions<SidebarCollapsedChangeReason>) => boolean | undefined
}

function reasonOf(options: unknown): { reason: SidebarCollapsedChangeReason; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<SidebarCollapsedChangeReason>
  return { reason, event: event instanceof Event ? event : undefined }
}

const sidebar = definePrimitive({
  name: "sidebar",
  options: { collapsed: "boolean", defaultCollapsed: "boolean", onCollapsedChange: "callback", controller: "value" },
  state: (options: SidebarOptions) => ({ collapsed: options.collapsed ?? options.defaultCollapsed ?? false }),
  sync: (options) => (options.collapsed === undefined ? {} : { collapsed: options.collapsed }),
  controlled: ["collapsed"],
  api: (context) => {
    const change = createChange(context)
    const setCollapsed = (collapsed: unknown, options?: ChangeOptions<SidebarCollapsedChangeReason>) => {
      if (typeof collapsed !== "boolean") throw new TypeError("setCollapsed takes true or false.")
      if (collapsed === context.store.get().collapsed) return false
      return change("collapsed", collapsed, reasonOf(options))
    }
    return {
      setCollapsed,
      collapse: (options?: ChangeOptions<SidebarCollapsedChangeReason>) => setCollapsed(true, options),
      expand: (options?: ChangeOptions<SidebarCollapsedChangeReason>) => setCollapsed(false, options),
      toggle: (options?: ChangeOptions<SidebarCollapsedChangeReason>) =>
        setCollapsed(!context.store.get().collapsed, options),
    }
  },
  slots: (slot) => ({
    root: slot({
      role: "navigation",
      attrs: (state) => ({ "data-collapsed": state.collapsed ? "" : undefined }),
    }),
    trigger: slot({
      attrs: (state) => ({
        type: "button",
        "aria-expanded": String(!state.collapsed),
        "data-collapsed": state.collapsed ? "" : undefined,
      }),
      press: ({ api }, event) => api.toggle({ reason: "trigger-press", event }),
    }),
  }),
  agent: { actions: ["collapse", "expand", "toggle", "setCollapsed"] },
})

function createSidebarController() {
  return createController<SidebarController>()
}

export { createSidebarController, sidebar }
export type { SidebarCollapsedChangeReason, SidebarController, SidebarOptions }

"use client"

import { renderElement } from "@ui-sdk/react/primitive"
import { createContext, createElement, use, useId, type ComponentProps, type ReactElement, type ReactNode } from "react"

import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

type TooltipTriggerProps = Omit<ComponentProps<typeof TooltipTrigger>, "render">

const SidebarRailContext = createContext(false)

type SidebarGroupProps = Omit<ComponentProps<"div">, "children"> & {
  label: string
  children: ReactNode
}

function SidebarGroup({ label, className, children, ...props }: SidebarGroupProps) {
  const labelId = useId()
  return (
    <div data-slot="sidebar-group" className={cn("flex flex-col gap-inline", className)} {...props}>
      <div
        id={labelId}
        data-slot="sidebar-group-label"
        className="truncate px-inset-item text-xs font-medium text-muted-foreground group-data-collapsed/sidebar:sr-only"
      >
        {label}
      </div>
      <ul aria-labelledby={labelId} className="flex flex-col gap-px">
        {children}
      </ul>
    </div>
  )
}

type SidebarItemProps = Omit<ComponentProps<"a">, "children"> & {
  icon?: ReactNode
  current?: boolean
  badge?: ReactNode
  render?: ReactElement<Record<string, unknown>>
  children: string
}

const itemClassName =
  "flex h-control w-full min-w-0 pointer-coarse:h-(--control-height-touch) items-center gap-inline rounded-control px-inset-item text-sm font-medium text-foreground outline-none transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring aria-[current=page]:bg-primary aria-[current=page]:text-primary-foreground group-data-collapsed/sidebar:justify-center group-data-collapsed/sidebar:px-0 [&_svg]:size-4 [&_svg]:shrink-0"

function SidebarItem({ icon, current = false, badge, render, className, children, ...props }: SidebarItemProps) {
  const rail = use(SidebarRailContext)
  const linkProps = {
    "data-slot": "sidebar-item",
    "data-current": current ? "" : undefined,
    "aria-current": current ? ("page" as const) : undefined,
    className: cn(itemClassName, className),
    ...props,
  }
  const content = (
    <>
      {icon}
      <span className="min-w-0 flex-1 truncate group-data-collapsed/sidebar:sr-only">{children}</span>
      {badge !== undefined && <span className="ms-auto text-xs group-data-collapsed/sidebar:hidden">{badge}</span>}
    </>
  )
  return (
    <li data-slot="sidebar-item-container">
      {rail ? (
        <Tooltip type="label">
          <TooltipTrigger render={render ?? createElement("a")} {...(linkProps as TooltipTriggerProps)}>
            {content}
          </TooltipTrigger>
          <TooltipContent side="right">{children}</TooltipContent>
        </Tooltip>
      ) : (
        renderElement("a", { ...linkProps, children: content }, render)
      )}
    </li>
  )
}

export { SidebarGroup, SidebarItem, SidebarRailContext }
export type { SidebarGroupProps, SidebarItemProps }

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import { createParts } from "@ui-sdk/react/primitive"
import { useMemo, useState, useSyncExternalStore, type ReactNode } from "react"

import { buttonVariants } from "@/components/ui/button"
import { Drawer, DrawerBackdrop, DrawerClose, DrawerContent, DrawerTitle, DrawerTrigger } from "@/components/ui/drawer"
import {
  createSidebarController,
  sidebar,
  type SidebarCollapsedChangeReason,
  type SidebarController,
} from "@/components/ui/sidebar-primitive"
import { SidebarGroup, SidebarItem, SidebarRailContext } from "@/components/ui/sidebar-items"
import { cn } from "@/lib/utils"

const { Root: SidebarRoot, Trigger: SidebarTrigger } = createParts(sidebar, { root: "nav", trigger: "button" })

type SidebarLabels = {
  collapse: string
  expand: string
  open: string
  close: string
}

const sidebarLabels: SidebarLabels = {
  collapse: "Collapse sidebar",
  expand: "Expand sidebar",
  open: "Open navigation",
  close: "Close navigation",
}

type SidebarProps = {
  label: string
  collapsed?: boolean
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean, details: ChangeDetails<SidebarCollapsedChangeReason>) => void
  collapsible?: boolean
  controller?: SidebarController
  narrowQuery?: string
  header?: ReactNode
  footer?: ReactNode
  labels?: Partial<SidebarLabels>
  className?: string
  children: ReactNode
}

function subscribeTo(query: string) {
  return (notify: () => void) => {
    if (typeof matchMedia !== "function") return () => {}
    const list = matchMedia(query)
    list.addEventListener("change", notify)
    return () => list.removeEventListener("change", notify)
  }
}

// The server and the first client render assume a wide screen, so hydration matches before the query runs.
function useNarrow(query: string) {
  const subscribe = useMemo(() => subscribeTo(query), [query])
  return useSyncExternalStore(
    subscribe,
    () => typeof matchMedia === "function" && matchMedia(query).matches,
    () => false,
  )
}

function PanelIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
      <rect x="3" y="4" width="18" height="16" rx="2" />
      <path d="M9 4v16" />
    </svg>
  )
}

const surfaceClassName = "flex min-h-0 flex-col gap-group text-foreground"

function Sidebar({
  label,
  collapsed: collapsedProp,
  defaultCollapsed = false,
  onCollapsedChange,
  collapsible = true,
  controller,
  narrowQuery = "(max-width: 767px)",
  header,
  footer,
  labels: labelOverrides,
  className,
  children,
}: SidebarProps) {
  const labels = { ...sidebarLabels, ...labelOverrides }
  const narrow = useNarrow(narrowQuery)
  const [ownCollapsed, setOwnCollapsed] = useState(defaultCollapsed)
  const [drawerOpen, setDrawerOpen] = useState(false)
  const collapsed = collapsible && !narrow && (collapsedProp ?? ownCollapsed)

  const body = <div className="flex min-h-0 flex-1 flex-col gap-group overflow-y-auto">{children}</div>

  if (narrow) {
    return (
      <Drawer side="start" open={drawerOpen} onOpenChange={setDrawerOpen}>
        <DrawerTrigger variant="ghost" size="icon" aria-label={labels.open} className={className}>
          <PanelIcon />
        </DrawerTrigger>
        <DrawerBackdrop />
        <DrawerContent
          className="gap-group p-items"
          onClickCapture={(event) => {
            if (event.target instanceof Element && event.target.closest("a[href]")) setDrawerOpen(false)
          }}
        >
          <div className="flex items-center gap-inline">
            <DrawerTitle className="flex-1 truncate px-inset-item text-base">{label}</DrawerTitle>
            <DrawerClose variant="ghost" size="icon" aria-label={labels.close}>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
                <path d="M18 6 6 18M6 6l12 12" />
              </svg>
            </DrawerClose>
          </div>
          <SidebarRoot aria-label={label} collapsed={false} className={cn(surfaceClassName, "flex-1")}>
            {header}
            {body}
            {footer}
          </SidebarRoot>
        </DrawerContent>
      </Drawer>
    )
  }

  return (
    <SidebarRoot
      aria-label={label}
      collapsed={collapsed}
      controller={controller}
      onCollapsedChange={(next, details) => {
        onCollapsedChange?.(next, details)
        if (!details.canceled) setOwnCollapsed(next)
      }}
      className={cn(
        surfaceClassName,
        "group/sidebar h-full w-(--sidebar-width) shrink-0 overflow-hidden border-e bg-muted/(--glass-opacity) p-items backdrop-surface transition-all duration-panel ease-standard data-collapsed:w-(--sidebar-rail-width) motion-reduce:transition-none",
        className,
      )}
    >
      <div data-slot="sidebar-header" className="flex items-center gap-inline group-data-collapsed/sidebar:flex-col">
        <div className="min-w-0 flex-1 group-data-collapsed/sidebar:hidden">{header}</div>
        {collapsible && (
          <SidebarTrigger
            aria-label={collapsed ? labels.expand : labels.collapse}
            className={cn(buttonVariants({ variant: "ghost", size: "icon" }), "rtl:[&_svg]:-scale-x-100")}
          >
            <PanelIcon />
          </SidebarTrigger>
        )}
      </div>
      <SidebarRailContext value={collapsed}>{body}</SidebarRailContext>
      {footer !== undefined && (
        <div data-slot="sidebar-footer" className="group-data-collapsed/sidebar:hidden">
          {footer}
        </div>
      )}
    </SidebarRoot>
  )
}

export { createSidebarController, Sidebar, SidebarGroup, SidebarItem, sidebarLabels }
export type { SidebarController, SidebarLabels, SidebarProps }
export type { SidebarGroupProps, SidebarItemProps } from "@/components/ui/sidebar-items"
